/* 18x16 battery widget bitmaps (MSB-first, 3 bytes/row), generated by
 * sim/gen_battery_widget.py — shell outline + terminal, reference-style
 * piercing bolt, and the bolt's 1px halo ring. Do not hand-edit. */
#define BATT_W 18
#define BATT_H 16
#define BATT_STRIDE ((BATT_W + 7) / 8)

static const uint8_t batt_shell[BATT_H * BATT_STRIDE] = {
    0x00, 0x00, 0x00, 0x00, 0x00, 0x00, 0xff, 0xff, 0x00, 0x80, 0x01, 0x00,
    0x80, 0x01, 0x00, 0x80, 0x01, 0x00, 0x80, 0x01, 0x80, 0x80, 0x01, 0x80,
    0x80, 0x01, 0x80, 0x80, 0x01, 0x80, 0x80, 0x01, 0x00, 0x80, 0x01, 0x00,
    0x80, 0x01, 0x00, 0xff, 0xff, 0x00, 0x00, 0x00, 0x00, 0x00, 0x00, 0x00,
};

static const uint8_t batt_bolt[BATT_H * BATT_STRIDE] = {
    0x00, 0x30, 0x00, 0x00, 0x60, 0x00, 0x00, 0x60, 0x00, 0x00, 0xc0, 0x00,
    0x00, 0xc0, 0x00, 0x01, 0x80, 0x00, 0x01, 0x80, 0x00, 0x07, 0xf0, 0x00,
    0x00, 0x60, 0x00, 0x00, 0xc0, 0x00, 0x00, 0xc0, 0x00, 0x01, 0x80, 0x00,
    0x01, 0x80, 0x00, 0x03, 0x00, 0x00, 0x06, 0x00, 0x00, 0x0c, 0x00, 0x00,
};

static const uint8_t batt_halo[BATT_H * BATT_STRIDE] = {
    0x00, 0x48, 0x00, 0x00, 0x90, 0x00, 0x00, 0x90, 0x00, 0x01, 0x20, 0x00,
    0x01, 0x20, 0x00, 0x02, 0x40, 0x00, 0x06, 0x70, 0x00, 0x08, 0x08, 0x00,
    0x07, 0x90, 0x00, 0x01, 0x20, 0x00, 0x01, 0x20, 0x00, 0x02, 0x40, 0x00,
    0x02, 0x40, 0x00, 0x04, 0x80, 0x00, 0x09, 0x00, 0x00, 0x12, 0x00, 0x00,
};

